import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    system = platform.system()
    if system == "Windows":
        cmd = ["wmic", "cpu", "get", "loadpercentage"]
    else:
        cmd = ["top", "-bn1", "|", "grep", "%Cpu(s)", "|", "awk", "{print $2}"]
    records = []
    iterations = int(duration // interval)
    for _ in range(iterations):
        timestamp = time.time()
        try:
            if system == "Windows":
                output = subprocess.check_output(cmd, shell=True).decode().strip().split('\n')[1].strip()
                cpu_usage = float(output)
            else:
                output = subprocess.check_output("top -bn1 | grep '%Cpu(s)' | awk '{print $2}'", shell=True).decode().strip()
                cpu_usage = float(output)
        except:
            cpu_usage = 0.0
        records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range, strict=False)
    result = {}
    for ip in network.hosts():
        try:
            response = subprocess.run(['ping', '-c', '1', '-W', '1', str(ip)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            result[str(ip)] = response.returncode == 0
        except subprocess.CalledProcessError:
            raise
    return result

